         SqliteSaver: new (opts: { path: string }) => MemorySaver;
       };
       return new SqliteSaver({ path: persistDir });
     } catch (err) {
       const message = err instanceof Error ? err.message : String(err);
       if (!message.includes('@langchain/langgraph-checkpoint-sqlite')) {
         throw err;
       }
     }
   }
